gbpP(){return"\u0642\u0627\u0644\u0628 \u062a\u0627\u06cc\u06cc\u062f\u200c\u0634\u062f\u0647 \u0628\u0631\u0627\u06cc \u0627\u0631\u0633\u0627\u0644 \u0644\u06cc\u0646\u06a9 \u06a9\u0627\u0631\u062a \u062d\u0633\u0627\u0628 \u06cc\u0627\u0641\u062a \u0646\u0634\u062f. \u0627\u0632 \u0628\u062e\u0634 \u0642\u0627\u0644\u0628\u200c\u0647\u0627\u06cc \u0646\u0648\u062a\u06cc\u0641\u06cc\u06a9\u06cc\u0634\u0646 \u06cc\u06a9 \u0642\u0627\u0644\u0628 \u0628\u0631\u0627\u06cc \u0631\u0648\u06cc\u062f\u0627\u062f \xab\u0627\u0631\u0633\u0627\u0644 \u0644\u06cc\u0646\u06a9 \u06a9\u0627\u0631\u062a \u062d\u0633\u0627\u0628\xbb \u062a\u0639\u0631\u06cc\u0641 \u0648 \u062a\u0627\u06cc\u06cc\u062f \u06a9\u0646\u06cc\u062f."},
gbpQ(){return"\u067e\u06cc\u0627\u0645\u06a9 \u0628\u0627 \u0645\u0648\u0641\u0642\u06cc\u062a \u0627\u0631\u0633\u0627\u0644 \u0634\u062f."},
gcMc(){return"\u0627\u0628\u062a\u062f\u0627 \u0644\u06cc\u0646\u06a9 \u0627\u06cc\u062c\u0627\u062f \u06a9\u0646\u06cc\u062f."},
gcMN(){return"\u0627\u0631\u0633\u0627\u0644 \u0628\u0647 \u0634\u0645\u0627\u0631\u0647 \u062f\u06cc\u06af\u0631 (\u0627\u062e\u062a\u06cc\u0627\u0631\u06cc)"},
