gcQ2(){return"\u062b\u0628\u062a \u0633\u0646\u062f \u062f\u0631\u06cc\u0627\u0641\u062a"},
gcQ3(){return"\u062f\u0631\u06cc\u0627\u0641\u062a \u0646\u0642\u062f\u06cc\u060c \u0628\u0627\u0646\u06a9\u06cc \u06cc\u0627 \u0686\u06a9 \u0647\u0645\u0631\u0627\u0647 \u0641\u0627\u06a9\u062a\u0648\u0631 \u062b\u0628\u062a \u0634\u0648\u062f. \u0645\u0627\u0646\u062f\u0647 \u0631\u0648\u06cc \u062d\u0633\u0627\u0628 \u0645\u0634\u062a\u0631\u06cc \u0645\u06cc\u200c\u0645\u0627\u0646\u062f."},
gbqM(){return"\u0635\u0646\u062f\u0648\u0642"},
gbqN(){return"\u0627\u0646\u062a\u062e\u0627\u0628 \u0635\u0646\u062f\u0648\u0642"},
gcQh(){return"\u0628\u0627\u0646\u06a9"},
gcQi(){return"\u0627\u0646\u062a\u062e\u0627\u0628 \u062d\u0633\u0627\u0628 \u0628\u0627\u0646\u06a9\u06cc"},
gcQj(){return"\u0686\u06a9"},
gcQk(){return"\u0627\u0646\u062a\u062e\u0627\u0628 \u06cc\u0627 \u062b\u0628\u062a \u0686\u06a9 \u062f\u0631\u06cc\u0627\u0641\u062a\u06cc"},
gcQg(){return"\u0645\u0628\u0644\u063a"},
gcQe(){return"+ \u0635\u0646\u062f\u0648\u0642"},
gcQd(){return"+ \u0628\u0627\u0646\u06a9"},
gcQf(){return"+ \u0686\u06a9"},
gcQl(){return"\u067e\u0631 \u06a9\u0631\u062f\u0646 \u0645\u0627\u0646\u062f\u0647"},
gcQu(){return"\u062d\u0630\u0641 \u0627\u06cc\u0646 \u067e\u0631\u062f\u0627\u062e\u062a"},
gcQp(){return"\u067e\u0631\u062f\u0627\u062e\u062a\u200c\u0634\u062f\u0647"},
gcQt(){return"\u0645\u0627\u0646\u062f\u0647"},
gcQz(){return"\u062a\u0633\u0648\u06cc\u0647 \u06a9\u0627\u0645\u0644"},
gcQq(){return"\u0645\u0627\u0646\u062f\u0647 \u0631\u0648\u06cc \u062d\u0633\u0627\u0628 \u0645\u0634\u062a\u0631\u06cc \u0645\u06cc\u200c\u0645\u0627\u0646\u062f"},
gcQn(){return"\u062c\u0645\u0639 \u067e\u0631\u062f\u0627\u062e\u062a\u200c\u0647\u0627 \u0627\u0632 \u0645\u0628\u0644\u063a \u0641\u0627\u06a9\u062a\u0648\u0631 \u0628\u06cc\u0634\u062a\u0631 \u0627\u0633\u062a"},
gcQs(){return"\u0645\u0627\u0646\u062f\u0647 \u0628\u0647\u200c\u0635\u0648\u0631\u062a \u0646\u0633\u06cc\u0647 \u0631\u0648\u06cc \u062d\u0633\u0627\u0628 \u0647\u0645\u06cc\u0646 \u0645\u0634\u062a\u0631\u06cc \u062b\u0628\u062a \u0645\u06cc\u200c\u0634\u0648\u062f."},
gcQr(){return"\u0645\u0627\u0646\u062f\u0647 \u0631\u0648\u06cc \u062d\u0633\u0627\u0628 \u0645\u0634\u062a\u0631\u06cc \u0646\u0627\u0634\u0646\u0627\u0633 \u062b\u0628\u062a \u0645\u06cc\u200c\u0634\u0648\u062f. \u0628\u0631\u0627\u06cc \u0646\u0633\u06cc\u0647\u060c \u0645\u0634\u062a\u0631\u06cc \u0648\u0627\u0642\u0639\u06cc \u0631\u0627 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0646\u06cc\u062f."},
gcQA(){return"\u0627\u0631\u0633\u0627\u0644 \u0644\u06cc\u0646\u06a9 \u0628\u0631\u0627\u06cc \u0645\u0627\u0646\u062f\u0647"},
gcQB(){return"\u0644\u06cc\u0646\u06a9 \u067e\u0631\u062f\u0627\u062e\u062a \u0622\u0646\u0644\u0627\u06cc\u0646 \u0641\u0642\u0637 \u0628\u0631\u0627\u06cc \u0645\u0628\u0644\u063a \u0628\u0627\u0642\u06cc\u200c\u0645\u0627\u0646\u062f\u0647 \u0627\u0631\u0633\u0627\u0644 \u0634\u0648\u062f"},
gcQx(){return"\u0628\u0631\u0627\u06cc \u067e\u0631\u062f\u0627\u062e\u062a \u0635\u0646\u062f\u0648\u0642\u060c \u0635\u0646\u062f\u0648\u0642 \u0631\u0627 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0646\u06cc\u062f"},
gcQw(){return"\u0628\u0631\u0627\u06cc \u067e\u0631\u062f\u0627\u062e\u062a \u0628\u0627\u0646\u06a9\u06cc\u060c \u062d\u0633\u0627\u0628 \u0628\u0627\u0646\u06a9 \u0631\u0627 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0646\u06cc\u062f"},
